"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { CalendarDays, Layers3, UsersRound } from "lucide-react";
import { UserRole, ROLE_LABELS } from "@/lib/types";

const ROLE_OPTIONS: UserRole[] = [
  "partner",
  "oak_staff",
  "coordination_team",
  "presenter",
  "observer",
];

export default function RegisterPage() {
  const router = useRouter();
  const [form, setForm] = useState({
    first_name: "",
    last_name: "",
    organisation: "",
    sub_partner: "",
    role: "" as UserRole | "",
    email: "",
    phone: "",
    dietary_requirements: "",
    accessibility_requirements: "",
    travel_requirements: "",
    accommodation_requirements: "",
    consent: false,
  });
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function update<K extends keyof typeof form>(key: K, value: (typeof form)[K]) {
    setForm((f) => ({ ...f, [key]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);

    if (!form.role) {
      setError("Please select your role.");
      return;
    }
    if (!form.consent) {
      setError("Please agree to the privacy policy to continue.");
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch("/api/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
        cache: "no-store",
      });
      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        setError(data.error || "Something went wrong. Please try again.");
        setSubmitting(false);
        return;
      }

      sessionStorage.setItem("oak_participant", JSON.stringify(data.participant));
      router.push(data.redirectTo);
    } catch {
      setError("Network error — please check your connection and try again.");
      setSubmitting(false);
    }
  }

  return (
    <div className="min-h-screen bg-[#eef1f4] md:flex">
      <aside className="hidden w-[240px] shrink-0 flex-col justify-between bg-white px-5 py-6 md:flex">
        <div>
          <div className="mb-6 flex items-center gap-3 text-left">
            <div className="grid h-10 w-10 place-items-center rounded-full border border-slate-300 text-lg font-light text-[#162e55]">
              O
            </div>
            <div>
              <p className="text-[9px] font-bold uppercase tracking-[0.28em] text-slate-500">OAK</p>
              <p className="text-[8px] font-bold uppercase tracking-[0.18em] text-slate-500">Foundation</p>
            </div>
          </div>

          <div className="mb-4 text-[9px] font-bold uppercase tracking-[0.24em] text-slate-400">
            Partner convening 2026
          </div>

          <button
            type="button"
            className="w-full rounded-xl bg-[#162e55] px-4 py-3 text-left text-sm font-medium text-white shadow-sm"
          >
            Register
          </button>
        </div>

        <div className="flex items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs text-slate-500">
          <div className="grid h-7 w-7 place-items-center rounded-full bg-[#edf3fb] text-[10px] font-bold text-slate-600">
            H
          </div>
          <div>
            <div className="font-semibold text-slate-700">Harare, Zimbabwe</div>
            <div>9–11 March 2026</div>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto px-3 py-6 sm:px-6">
        <div className="mx-auto w-full max-w-[560px]">
          <div className="overflow-hidden rounded-[22px] bg-[#162e55] p-5 text-white shadow-[0_10px_30px_rgba(15,23,42,0.08)] sm:p-6">
            <h1 className="text-[28px] font-bold leading-none tracking-[-0.04em] sm:text-[36px]">
              Partner<br />Convening 2026
            </h1>
            <p className="mt-2 text-sm text-blue-100">Harare • 9–11 March 2026</p>
          </div>

          <div className="mt-4 grid grid-cols-3 gap-2 sm:gap-3">
            <EventStat icon={UsersRound} value="110+" label="Attendees" />
            <EventStat icon={CalendarDays} value="24" label="Sessions" />
            <EventStat icon={Layers3} value="38" label="Partners" />
          </div>

          <form
            onSubmit={handleSubmit}
            className="mt-4 rounded-[22px] bg-white px-4 py-5 shadow-[0_10px_30px_rgba(15,23,42,0.08)] sm:px-5"
          >
            <h2 className="mb-5 text-center text-[18px] font-bold text-slate-900">
              Registration Form
            </h2>

            <div className="grid gap-4 sm:grid-cols-2">
              <Field label="First Name" required>
                <input
                  required
                  value={form.first_name}
                  onChange={(e) => update("first_name", e.target.value)}
                  className="input"
                  placeholder="Maria"
                />
              </Field>
              <Field label="Last Name" required>
                <input
                  required
                  value={form.last_name}
                  onChange={(e) => update("last_name", e.target.value)}
                  className="input"
                  placeholder="Schmidt"
                />
              </Field>
            </div>

            <div className="mt-4">
              <Field label="Organisation" required>
                <input
                  required
                  value={form.organisation}
                  onChange={(e) => update("organisation", e.target.value)}
                  className="input"
                  placeholder="Your organisation name"
                />
              </Field>
            </div>

            <div className="mt-4">
              <Field label="Sub-Partner / Programme Area">
                <input
                  value={form.sub_partner}
                  onChange={(e) => update("sub_partner", e.target.value)}
                  className="input"
                  placeholder="Optional"
                />
              </Field>
            </div>

            <div className="mt-4">
              <Field label="Role / Capacity" required>
                <select
                  required
                  value={form.role}
                  onChange={(e) => update("role", e.target.value as UserRole)}
                  className="input"
                >
                  <option value="">Select your role</option>
                  {ROLE_OPTIONS.map((r) => (
                    <option key={r} value={r}>
                      {ROLE_LABELS[r]}
                    </option>
                  ))}
                </select>
              </Field>
            </div>

            <div className="mt-4 grid gap-4 sm:grid-cols-2">
              <Field label="Email Address" required>
                <input
                  required
                  type="email"
                  value={form.email}
                  onChange={(e) => update("email", e.target.value)}
                  className="input"
                  placeholder="your@organisation.org"
                />
              </Field>
              <Field label="Phone Number">
                <input
                  value={form.phone}
                  onChange={(e) => update("phone", e.target.value)}
                  className="input"
                  placeholder="+44 xxx xxx xxx"
                />
              </Field>
            </div>

            <div className="mt-5 rounded-xl bg-[#eef2f6] p-3 sm:p-4">
              <p className="mb-3 text-center text-[11px] font-bold uppercase tracking-[0.18em] text-slate-500">
                Requirements
              </p>

              <div className="space-y-3">
                <Field label="Dietary Requirements">
                  <textarea
                    rows={2}
                    value={form.dietary_requirements}
                    onChange={(e) => update("dietary_requirements", e.target.value)}
                    className="input min-h-[72px] resize-none"
                    placeholder="e.g. Vegetarian, Halal, Gluten-free"
                  />
                </Field>

                <Field label="Accessibility Requirements">
                  <textarea
                    rows={2}
                    value={form.accessibility_requirements}
                    onChange={(e) => update("accessibility_requirements", e.target.value)}
                    className="input min-h-[72px] resize-none"
                    placeholder="e.g. Wheelchair access, hearing loop"
                  />
                </Field>

                <Field label="Travel & Accommodation">
                  <textarea
                    rows={2}
                    value={form.travel_requirements}
                    onChange={(e) => update("travel_requirements", e.target.value)}
                    className="input min-h-[72px] resize-none"
                    placeholder="e.g. Flight from London, hotel needed"
                  />
                </Field>
              </div>
            </div>

            <label className="mt-5 flex items-start gap-3 rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-[12px] text-slate-600">
              <input
                type="checkbox"
                checked={form.consent}
                onChange={(e) => update("consent", e.target.checked)}
                className="mt-1 h-4 w-4 accent-[#162e55]"
              />
              <span>
                I agree to OAK Foundation&apos;s privacy policy and consent to my
                registration data being used for event coordination.
              </span>
            </label>

            {error && (
              <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">
                {error}
              </p>
            )}

            <button
              type="submit"
              disabled={submitting}
              className="mt-5 w-full rounded-xl bg-[#162e55] py-3.5 text-sm font-semibold text-white shadow-sm transition hover:bg-[#0f1f3d] disabled:opacity-60"
            >
              {submitting ? "Registering…" : "Register & Generate QR Code"}
            </button>
          </form>

          <p className="mt-3 text-center text-[11px] text-slate-400">
            Your data is securely handled by OAK Foundation in accordance with GDPR.
          </p>
        </div>
      </main>
    </div>
  );
}

function EventStat({
  icon: Icon,
  value,
  label,
}: {
  icon: typeof UsersRound;
  value: string;
  label: string;
}) {
  return (
    <div className="rounded-[14px] border border-slate-200 bg-white px-3 py-3 text-center shadow-[0_2px_8px_rgba(15,23,42,0.04)]">
      <Icon aria-hidden="true" className="mx-auto h-4 w-4 text-[#6c7e9c]" strokeWidth={1.8} />
      <p className="mt-2 text-[18px] font-extrabold leading-none text-[#162e55]">{value}</p>
      <p className="mt-1 text-[10px] uppercase tracking-[0.12em] text-slate-400">{label}</p>
    </div>
  );
}

function Field({
  label,
  required,
  children,
}: {
  label: string;
  required?: boolean;
  children: React.ReactNode;
}) {
  return (
    <label className="block">
      <span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.15em] text-slate-500">
        {label} {required && <span className="text-red-500">*</span>}
      </span>
      {children}
    </label>
  );
}